using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class HousesPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Houses", "View"); return AdminDataService.GetList("Houses"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Houses", "View"); return AdminDataService.GetDefinitionMetadata("Houses"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Houses", "Delete"); return AdminDataService.Delete("Houses", id); } } }
